// ═══ CONDITION 1: MUTUAL EXCLUSION ═══
// Locks are exclusive — only one thread holds them.
// Can we break this? Use ReadWriteLock (shared reads) or lock-free (Atomic/CHM).
// Partially: ReadWriteLock allows multiple readers. But writes are still exclusive.
// Fully: lock-free (CAS) eliminates mutual exclusion entirely.

// ═══ CONDITION 2: HOLD AND WAIT ═══
// Thread holds Lock-A while waiting for Lock-B.
// Break: acquire ALL locks at once (atomically), or release before requesting another.
boolean transferAllOrNothing(Account a, Account b) {
    // tryLock both — if can't get both, release what you have
    if (lockA.tryLock()) {
        try {
            if (lockB.tryLock()) {
                try { return doTransfer(); }
                finally { lockB.unlock(); }
            }
        } finally { lockA.unlock(); }
    }
    return false;  // couldn't get both → no hold-and-wait!
}

// ═══ CONDITION 3: NO PREEMPTION ═══
// Can't forcibly take a lock from another thread.
// Break: tryLock with timeout — thread gives up voluntarily.
if (!lock.tryLock(5, TimeUnit.SECONDS)) {
    // Couldn't acquire → voluntarily back off (simulates preemption)
    return RETRY_LATER;
}

// ═══ CONDITION 4: CIRCULAR WAIT (easiest to break!) ═══
// Thread-1: holds A, wants B. Thread-2: holds B, wants A. CIRCLE!
// Break: assign a GLOBAL ORDER to all locks. Always acquire in that order.
void transfer(Account from, Account to) {
    // ORDER by account ID — same order for ALL threads!
    Account first = from.id.compareTo(to.id) < 0 ? from : to;
    Account second = first == from ? to : from;
    synchronized (first.lock) {     // always lower ID first
        synchronized (second.lock) { // then higher ID
            // No circular wait possible!
        }
    }
}

// ═══ WHY breaking ONE condition is enough ═══
// Deadlock = Condition1 AND Condition2 AND Condition3 AND Condition4
// FALSE = TRUE AND TRUE AND TRUE AND FALSE
// If ANY condition is FALSE → entire expression is FALSE → no deadlock!

// ═══ WHICH TO BREAK? (practicality ranking) ═══
// 1. Circular wait (lock ordering) — easiest, most common ✅
// 2. Hold-and-wait (tryLock both) — practical, needs retry logic
// 3. No preemption (tryLock timeout) — good fallback
// 4. Mutual exclusion (lock-free) — hardest, not always possible
