// ─── File: src/test/java/com/bank/coffman/CoffmanConditionsTest.java ───
package com.bank.coffman;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import static org.assertj.core.api.Assertions.*;

class CoffmanConditionsTest {

    static class Account {
        final String id;
        final ReentrantLock lock = new ReentrantLock();
        int balance;
        Account(String id, int balance) { this.id = id; this.balance = balance; }
    }

    // ═══ BREAK CIRCULAR WAIT: lock ordering for N accounts ═══
    static void multiAccountTransfer(List<Account> accounts, int[] amounts) {
        // Sort by ID → consistent order → no circular wait!
        List<Account> sorted = new ArrayList<>(accounts);
        sorted.sort(Comparator.comparing(a -> a.id));

        // Lock ALL in order
        for (Account a : sorted) a.lock.lock();
        try {
            for (int i = 0; i < accounts.size(); i++) {
                accounts.get(i).balance += amounts[i];
            }
        } finally {
            // Unlock in reverse order (good practice)
            for (int i = sorted.size() - 1; i >= 0; i--) {
                sorted.get(i).lock.unlock();
            }
        }
    }

    @Test
    void breakCircularWait_lockOrdering_noDeadlock() throws InterruptedException {
        Account a = new Account("ACC-A", 100000);
        Account b = new Account("ACC-B", 100000);
        Account c = new Account("ACC-C", 100000);
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            final int idx = i;
            new Thread(() -> {
                // Random account combinations — but always locked in sorted order!
                if (idx % 3 == 0) multiAccountTransfer(List.of(a, b), new int[]{-1000, 1000});
                else if (idx % 3 == 1) multiAccountTransfer(List.of(b, c), new int[]{-1000, 1000});
                else multiAccountTransfer(List.of(c, a), new int[]{-1000, 1000});
                latch.countDown();
            }).start();
        }

        boolean done = latch.await(10, TimeUnit.SECONDS);
        assertThat(done).isTrue();  // no deadlock!
        int total = a.balance + b.balance + c.balance;
        assertThat(total).isEqualTo(300000);  // money conserved!
    }

    // ═══ BREAK HOLD-AND-WAIT: tryLock both or none ═══
    static boolean tryTransfer(Account from, Account to, int amount) {
        boolean gotFrom = false, gotTo = false;
        try {
            gotFrom = from.lock.tryLock(100, TimeUnit.MILLISECONDS);
            gotTo = to.lock.tryLock(100, TimeUnit.MILLISECONDS);
            if (gotFrom && gotTo) {
                from.balance -= amount;
                to.balance += amount;
                return true;
            }
            return false;  // couldn't get both — release and retry
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        } finally {
            if (gotTo) to.lock.unlock();
            if (gotFrom) from.lock.unlock();
        }
    }

    @Test
    void breakHoldAndWait_tryLock() throws InterruptedException {
        Account from = new Account("SAV2001", 100000);
        Account to = new Account("CUR3001", 0);
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                while (!tryTransfer(from, to, 1000)) { /* retry */ }
                latch.countDown();
            }).start();
        }

        latch.await(10, TimeUnit.SECONDS);
        assertThat(from.balance + to.balance).isEqualTo(100000);
    }

    // ═══ BREAK MUTUAL EXCLUSION: lock-free (Atomic) ═══
    @Test
    void breakMutualExclusion_lockFree() throws InterruptedException {
        java.util.concurrent.atomic.AtomicInteger balance = new java.util.concurrent.atomic.AtomicInteger(100000);
        int threads = 100;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                balance.addAndGet(-1000);  // atomic! No lock! No deadlock possible!
                latch.countDown();
            }).start();
        }
        latch.await();
        assertThat(balance.get()).isEqualTo(0);
    }
}
